"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { useLivingShader, type FieldMotionProps } from "@/lib/sahajiv/living-shader";

export type PigmentFieldProps = Omit<React.ComponentProps<"div">, "children" | "ref"> & FieldMotionProps;

/** A decorative pigment wash. Give its parent a height and place content beside it. */
export function PigmentField({ speed = 1, intensity = 1, tone = "balanced", paused = false, className, style, ...props }: PigmentFieldProps) {
  const { host: hostRef, canvas: canvasRef, status, tone: safeTone, intensity: safeIntensity, moving } = useLivingShader("pigment", { speed, intensity, tone, paused });
  return (
    <div {...props} ref={hostRef} data-slot="pigment-field" data-tone={safeTone} data-renderer={status} data-moving={moving ? "true" : "false"} className={cn("v-pigment-field", className)} style={{ ...style, "--field-intensity": safeIntensity } as React.CSSProperties} aria-hidden="true" inert>
      <span data-slot="field-fallback" />
      <canvas ref={canvasRef} data-slot="field-canvas" aria-hidden="true" />
    </div>
  );
}

@layer sahajiv-states {
.v-pigment-field {
  --field-a: var(--v-pink, #f5b8db);
  --field-b: var(--v-blue, #b6caeb);
  --field-c: var(--v-yellow, #f5d867);
  position: absolute;
  inset: 0;
  overflow: hidden;
  border-radius: inherit;
  pointer-events: none;
  user-select: none;
  isolation: isolate;
  background: var(--v-paper, #fbf4e6);
  contain: paint;
}
.v-pigment-field[data-tone="warm"] { --field-b: var(--v-yellow, #f5d867); --field-c: var(--v-olive, #9aab63); }
.v-pigment-field[data-tone="cool"] { --field-a: var(--v-blue, #b6caeb); --field-b: var(--v-olive, #9aab63); --field-c: var(--v-pink, #f5b8db); }
.v-pigment-field > [data-slot="field-fallback"] {
  position: absolute;
  inset: 0;
  opacity: clamp(0, var(--field-intensity, 1), 1);
  background: radial-gradient(ellipse at 18% 35%, color-mix(in srgb, var(--field-a) 65%, transparent), transparent 62%), radial-gradient(ellipse at 82% 72%, color-mix(in srgb, var(--field-b) 60%, transparent), transparent 62%), radial-gradient(ellipse at 56% 8%, color-mix(in srgb, var(--field-c) 40%, transparent), transparent 56%);
}
.v-pigment-field > [data-slot="field-canvas"] { position: absolute; inset: 0; width: 100%; height: 100%; display: block; opacity: 0; pointer-events: none; }
.v-pigment-field[data-renderer="webgl"] > [data-slot="field-canvas"] { opacity: 1; }
@media (forced-colors: active) { .v-pigment-field { visibility: hidden; } }

}
